<?php namespace App\Services; use App\Models\Reminder; use Illuminate\Support\Facades\Notification; use App\Notifications\ReminderDueNotification; class ReminderService { public function sendDue():int { $count=0; Reminder::with('user','pet')->where('is_active',true)->whereNull('completed_at')->whereBetween('due_at',[now()->subMinutes(30),now()->addMinutes(60)])->chunkById(100,function($rows)use(&$count){foreach($rows as $r){$r->user->notify(new ReminderDueNotification($r));$count++;}}); return $count; } }